// deterministic simple PRNG
let seed = 12345;
function rand() {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
}
function ri(n: number) { return Math.floor(rand() * n); }

function resultEqual(a: any, b: any): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}

const itemPool = ["apple", "banana", "cherry"];
const idPool = ["A", "B", "C", "D", "E"];

function genEvent(id: string) {
  const r = rand();
  const item = itemPool[ri(itemPool.length)];
  const qty = 1 + ri(5);
  if (r < 0.25) return { type: "order", id, item, qty };
  if (r < 0.42) return { type: "cancel", id };
  if (r < 0.6) {
    // ship: sometimes omit qty, sometimes wrong
    if (rand() < 0.3) return { type: "ship", id };
    return { type: "ship", id, qty: 1 + ri(6) };
  }
  if (r < 0.78) return { type: "restock", item, qty };
  if (r < 0.9) return { type: "expire", id };
  return { type: "order", id, item, qty }; // default back to order
}

